import{bQ as t,aL as l,u as o,G as a}from"./chunks/framework.C1gZXFVa.js";const p=JSON.parse('{"title":"自制离线包","description":"","frontmatter":{},"headers":[],"relativePath":"guide/build.md","filePath":"guide/build.md"}'),i={name:"guide/build.md"};function s(c,e,d,n,r,h){return l(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="自制离线包" tabindex="-1">自制离线包 <a class="header-anchor" href="#自制离线包" aria-label="Permalink to &quot;自制离线包&quot;">​</a></h1><blockquote><p>绝大多数人<strong>不需要</strong>自己打包：现成包已经覆盖 4 个系统 × 2 种架构（见<a href="/guide/platforms">平台支持矩阵</a>），直接<a href="/guide/download">下载</a>即可。只有下面两种情况才需要自己打包：</p><ul><li>想换 Ansible 版本；</li><li>想增减随包附带的 collections。</li></ul></blockquote><h2 id="打包步骤" tabindex="-1">打包步骤 <a class="header-anchor" href="#打包步骤" aria-label="Permalink to &quot;打包步骤&quot;">​</a></h2><ol><li><p>准备一台<strong>打包机</strong>，它必须同时满足：</p><ul><li>能上网</li><li>系统 / CPU 架构 / Python 版本与离线机<strong>一致</strong></li></ul></li><li><p>克隆主仓库后运行打包脚本：</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/make-offline-bundle.sh</span></span></code></pre></div><ol start="3"><li>产物在仓库的 <code>dist/</code> 目录下：<code>ansible-offline-install-2.0.0-bundle.tar.gz</code> 和它的 <code>.sha256</code> 校验文件。拷到离线机上按<a href="/guide/quick-start">快速开始</a>的第二、三步操作即可。</li></ol><blockquote><p>🌏 脚本默认中文，<code>bash scripts/make-offline-bundle.sh --lang en</code> 或环境变量 <code>ANSIBLE_OFFLINE_LANG=en</code> 可切英文。</p></blockquote><h2 id="可选项-环境变量" tabindex="-1">可选项（环境变量） <a class="header-anchor" href="#可选项-环境变量" aria-label="Permalink to &quot;可选项（环境变量）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环境变量</th><th>作用</th></tr></thead><tbody><tr><td><code>WITH_COLLECTIONS=0</code></td><td>只打包 Ansible 本体，不带 collections，包更小</td></tr><tr><td><code>PYTHON_BIN=python3.11</code></td><td>指定用哪个 Python 打包（系统里有多个 Python 时）；不指定时脚本会自动探测 python3.13 / 3.12 / 3.11 中第一个满足 &gt;= 3.11 的解释器</td></tr><tr><td><code>PIP_INDEX_URL=https://pypi.tuna.tsinghua.edu.cn/simple</code></td><td>海外网络不通时给 pip 换国内源（示例为清华源，也可换阿里云源）</td></tr></tbody></table><blockquote><p>另外，想换 Ansible 版本：改 <code>requirements.txt</code> 里 <code>ansible-core</code> 的版本号再打包。</p></blockquote><h2 id="随包-collections" tabindex="-1">随包 collections <a class="header-anchor" href="#随包-collections" aria-label="Permalink to &quot;随包 collections&quot;">​</a></h2><ul><li>从 Releases 下载的离线包里已经包含 <code>ansible.posix</code> 和 <code>community.general</code>（含它们的依赖），运行 <code>install.sh</code> 时会自动装好，无需任何额外操作。</li><li><code>collections-requirements.yml</code> 记录了清单细节；想增减 collection 名单，改这个文件后重新打包即可。</li><li>安装时不想装 collections：<code>INSTALL_COLLECTIONS=0 bash install.sh</code>。</li></ul><div class="warning custom-block"><p class="custom-block-title">注意：collections 的来源</p><p>collections 是从海外的 Ansible Galaxy 下载的，国内没有稳定镜像。打包机连不通 Galaxy 时，这一步会失败；这种情况请直接用 Releases 里的现成包，现成包里已经包含 collections。</p></div>',13)])])}const b=t(i,[["render",s]]);export{p as __pageData,b as default};
